import{_ as r,C as t,o,c as s,E as a,a2 as d}from"./chunks/framework.BdWD-ld-.js";const g=JSON.parse('{"title":"The Confirmation Asked. What Did the Risk Analyzer Actually See?","description":"","frontmatter":{"title":"The Confirmation Asked. What Did the Risk Analyzer Actually See?","article_type":"technical-analysis","edition":"research-center","research_question":"确认请求能说明动作被审查到什么程度，而不能说明哪些环境危险已被识别？","summary":"Unknown risk can request confirmation, and an analyzer exception can become HIGH. Neither establishes that environmental hazards were detected. Pinned source, an internal isolated probe and independently authored hazard research show how to inspect the evidence reaching a decision.","sources":"https://docs.openhands.dev/sdk/guides/security; https://arxiv.org/html/2611.26553v1","date":"2026-11-23","column":"digital-employee","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261123-003","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-23-sig-20261123-003-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/digital-employee/2026-11-23-sig-20261123-003.md","filePath":"en/digital-employee/2026-11-23-sig-20261123-003.md","lastUpdated":null}'),c={name:"en/digital-employee/2026-11-23-sig-20261123-003.md"};function l(h,e,p,u,m,f){const n=t("ArticleCover"),i=t("ArticleTableScroll");return o(),s("div",null,[a(n,{image:"/assets/covers/daily-2026-11-23-sig-20261123-003-cover.png",kicker:"Research",title:"The Confirmation Asked. What Did the Risk Analyzer Actually See?",summary:"Unknown risk can request confirmation, and an analyzer exception can become HIGH. Neither establishes that environmental hazards were detected. Pinned source, an internal isolated probe and independently authored hazard research show how to inspect the evidence reaching a decision.",version:"2026-11-23",languageHref:"/zh/digital-employee/2026-11-23-sig-20261123-003",languageLabel:"中文"}),a(i,{language:"en"}),e[0]||(e[0]=d('<h1 id="the-confirmation-asked-what-did-the-risk-analyzer-actually-see" tabindex="-1">The Confirmation Asked. What Did the Risk Analyzer Actually See? <a class="header-anchor" href="#the-confirmation-asked-what-did-the-risk-analyzer-actually-see" aria-label="Permalink to &quot;The Confirmation Asked. What Did the Risk Analyzer Actually See?&quot;">​</a></h1><p>In the admitted internal isolated probe, the same UNKNOWN-risk input changed from “request confirmation” to “do not request confirmation” when one configuration flag changed. The question on screen first establishes a policy decision. It does not establish which hazards the analyzer recognized. Engineers responsible for agent action review need to trace the target environment, supporting observations and confirmation decision separately.</p><h2 id="the-question-is-downstream-of-an-observation" tabindex="-1">The question is downstream of an observation <a class="header-anchor" href="#the-question-is-downstream-of-an-observation" aria-label="Permalink to &quot;The question is downstream of an observation&quot;">​</a></h2><p>The OpenHands security guide assigns different jobs to an analyzer and a confirmation policy: one evaluates risk; the other decides whether to ask. Always asking, never asking and asking according to risk are different policies. Configuring an analyzer alone does not activate confirmation. <a href="https://docs.openhands.dev/sdk/guides/security" target="_blank" rel="noreferrer">Official security guide</a></p><p>The pinned risk-based policy defaults to a HIGH threshold and requests confirmation for UNKNOWN by default. UNKNOWN cannot itself be the threshold. For known risk, the method delegates comparison to the risk comparator. This maps an assessment into a question; it does not establish that the assessment had complete information. <a href="https://raw.githubusercontent.com/OpenHands/software-agent-sdk/ebec01b3893696c2f5454762eb44796c71bb391a/openhands-sdk/openhands/sdk/security/confirmation_policy.py" target="_blank" rel="noreferrer">Pinned confirmation source</a></p><p>Consider an explicitly illustrative request to “clean temporary files” whose resolved directory could point at a protected resource. This is not a discovered OpenHands vulnerability. It identifies an inspection question: did the actual target, environment and possible consequence reach analysis? A correctly functioning confirmation mechanism can still ask a person to decide with incomplete information.</p><h2 id="unknown-risk-and-failed-analysis-are-different-cases" tabindex="-1">Unknown risk and failed analysis are different cases <a class="header-anchor" href="#unknown-risk-and-failed-analysis-are-different-cases" aria-label="Permalink to &quot;Unknown risk and failed analysis are different cases&quot;">​</a></h2><p>The same-date Analysis stage executed a source-derived internal isolated probe. It extracted the pinned confirmation method and base batch helper, preserved their bodies, removed decorators and supplied declared dependency stubs. These are the persisted outputs, not integration tests rerun for this article.</p><table tabindex="0"><thead><tr><th>Input and control</th><th>Observed output</th><th>Supported scope</th></tr></thead><tbody><tr><td>UNKNOWN, unknown-confirmation flag enabled</td><td>Request confirmation</td><td>The method&#39;s default branch</td></tr><tr><td>Same UNKNOWN input, only that flag disabled</td><td>No confirmation</td><td>Configuration changes this branch</td></tr><tr><td>Analyzer normally returns LOW</td><td>LOW, no detail</td><td>Base helper&#39;s normal path</td></tr><tr><td>Analyzer raises a controlled exception</td><td>HIGH, error retained in detail</td><td>Base helper&#39;s exception fallback</td></tr></tbody></table><p>An unavailable reliable classification therefore needs further distinction: unknown information and a failed analysis process are different cases. The helper converts the latter into HIGH. It does not resolve the error or establish that execution will be blocked; the resulting behavior also depends on policy and the actual calling path. <a href="https://raw.githubusercontent.com/OpenHands/software-agent-sdk/ebec01b3893696c2f5454762eb44796c71bb391a/openhands-sdk/openhands/sdk/security/analyzer.py" target="_blank" rel="noreferrer">Pinned analyzer source</a></p><p>The internal probe exercised neither the complete SDK nor the risk comparator, configuration validation, approval UI or conversation loop. It measured no hazard-detection capability. Calling these local outputs a safety-effectiveness test would extend function evidence into unobserved effects. <a href="/joinwell52/assets/evidence/2026-11-23-sig-20261123-003/experiment-evidence.json">Internal experiment inputs, outputs and limits</a></p><h2 id="environmental-evidence-changes-the-question" tabindex="-1">Environmental evidence changes the question <a class="header-anchor" href="#environmental-evidence-changes-the-question" aria-label="Permalink to &quot;Environmental evidence changes the question&quot;">​</a></h2><p>The independently authored ROGUE-AI study from Texas A&amp;M compares reconstructed incident environments with minimally changed controls and checks harm from environment state rather than trusting an agent&#39;s final message. The authors classify 62 of 72 catalogued real-world-harm incidents as involving no attacker. That describes their selected cases, not the population frequency of agent incidents. <a href="https://arxiv.org/html/2611.26553v1" target="_blank" rel="noreferrer">Preprint v1, sections 3–6</a></p><p>Its useful contribution here is that ordinary task-directed behavior can encounter hazards without malicious instructions. In a selected set of 7–11 frequently harmful reconstructions per model, the authors report that repeated hazard-and-consequence warnings reduced harm more than equal-length neutral notes. Substantial residual harm varies by model. These are selected synthetic conditions, not a deployment risk-reduction estimate; their percentages cannot simply be subtracted from whole-suite rates.</p><p>Reconstruction also introduces uncertainty. Seven reconstructions fail the state-difference condition; some mail-server cases partly measure component behavior rather than model choice. Blind rebuilds disagree on five of eleven incident outcomes. Confirmation is simulated without an adaptive comparison. The study motivates examining information supplied before a decision. It does not test the cited SDK configuration or independently reproduce its safety effects.</p><h2 id="inspect-the-evidence-that-reaches-the-decision" tabindex="-1">Inspect the evidence that reaches the decision <a class="header-anchor" href="#inspect-the-evidence-that-reaches-the-decision" aria-label="Permalink to &quot;Inspect the evidence that reaches the decision&quot;">​</a></h2><p>Our engineering interpretation is to preserve what was observed, how it was rated, what was decided and what actually happened as distinguishable evidence. The following is a proposed inspection record, not a promised project interface or a required storage design.</p><table tabindex="0"><thead><tr><th>Handoff</th><th>Responsible inspector</th><th>Evidence to retain</th><th>Insufficient basis for proceeding</th></tr></thead><tbody><tr><td>Action resolution to environment observation</td><td>Caller and environment adapter</td><td>Resolved target, observation time, reachable authority, protected-resource state</td><td>Target or environment cannot be established</td></tr><tr><td>Observation to risk analysis</td><td>Analyzer maintainer</td><td>Identified hazard, expected consequence, rating rationale, missing information</td><td>Rating exists but its basis is untraceable</td></tr><tr><td>Analysis to human decision</td><td>Policy and approval-interface maintainers</td><td>Actual policy configuration, displayed action/environment, decision target</td><td>Displayed and pending actions cannot be correlated</td></tr><tr><td>Decision to effect inspection</td><td>Executor and domain evaluator</td><td>Actual action and resulting state</td><td>Approval exists without effect evidence</td></tr></tbody></table><p>For the illustrative cleanup request, begin by tracing directory resolution and the source of observations, then check whether those facts reach the analyzer and approver. Do not fill the record with a plausible hazard description. Missing observations remain missing. The deployment policy must specify whether to stop and how to obtain more information; a general example cannot decide its risk policy.</p><p>This separates information loss from judgment failure. An analyzer receiving too little information is a different diagnosis from an analyzer making a poor judgment with sufficient evidence. An approver never seeing a hazard differs from an approver seeing it and proceeding. Counting confirmation prompts cannot make these distinctions.</p><h2 id="evidence-and-sources" tabindex="-1">Evidence and sources <a class="header-anchor" href="#evidence-and-sources" aria-label="Permalink to &quot;Evidence and sources&quot;">​</a></h2><p>Public implementation facts, source reports and internal experiments have different roles. Source shows what a pinned version contains. Study numbers are author reports. The internal probe tests two local methods. The inspection record is our interpretation and has no measured deployment benefit.</p><ul><li><a href="https://docs.openhands.dev/sdk/guides/security" target="_blank" rel="noreferrer">Official security guide</a>: snapshot read on 2026-11-23; supports the division between analysis and confirmation and its stated limits. Direct tool execution is outside the described conversation-loop protection; classification is not a sandbox or hard denial. No bypass attack was executed here.</li><li><a href="https://raw.githubusercontent.com/OpenHands/software-agent-sdk/ebec01b3893696c2f5454762eb44796c71bb391a/openhands-sdk/openhands/sdk/security/confirmation_policy.py" target="_blank" rel="noreferrer">Confirmation implementation</a> and <a href="https://raw.githubusercontent.com/OpenHands/software-agent-sdk/ebec01b3893696c2f5454762eb44796c71bb391a/openhands-sdk/openhands/sdk/security/analyzer.py" target="_blank" rel="noreferrer">analyzer implementation</a>: pinned to the linked commit. Documentation and code share one maintainer actor; they are not two independent sources.</li><li><a href="https://arxiv.org/html/2611.26553v1" target="_blank" rel="noreferrer">ROGUE-AI v1</a>: preprint by Mengxiao Wang, Mahbub Alam, Kalyan Nakka and Nitesh Saxena. Its separate authorship does not make it independent validation of this implementation. Operational incident archives were not obtained and reconstructions were not executed here.</li></ul><h2 id="what-this-comparison-cannot-establish" tabindex="-1">What this comparison cannot establish <a class="header-anchor" href="#what-this-comparison-cannot-establish" aria-label="Permalink to &quot;What this comparison cannot establish&quot;">​</a></h2><p>Asking about every action cannot automatically repair missing environment information. Conversely, for a fixed, isolated task without hazardous side effects whose relevant environment facts are already complete, another generic hazard checklist may add nothing. Prompt presence alone distinguishes neither case.</p><p>This article measures no deployment&#39;s detection rate, false-positive rate or harm reduction. A next experiment could hold the action fixed in a protected test environment, vary visible target-and-consequence information, and retain the analysis rationale, human-visible content and actual state. It could then test whether added information improves decisions. A separate check must ask whether an earlier decision still corresponds to the same action after the environment changes during a wait. Until those tests exist, missing observation and unvalidated effectiveness remain distinct gaps.</p>',26))])}const v=r(c,[["render",l]]);export{g as __pageData,v as default};
